				me._mq_timer_b.ggTimeout=Number("0.35") * 1000.0;
				me._mq_timer_b.ggTimestamp=skin.ggCurrentTime;
				if (player.transitionsDisabled) {
					me._mq_text_.style.transition='none';
				} else {
					me._mq_text_.style.transition='all 350ms ease-out 0ms';
				}
				me._mq_text_.ggParameter.rx=0;me._mq_text_.ggParameter.ry=-22;
				me._mq_text_.style.transform=parameterToTransform(me._mq_text_.ggParameter);
